pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BaseEscalationManager c;

    function setUp() public {
        c = new BaseEscalationManager();
    }

    function _testUnauthorizedRequestPriceReverts(address caller, bytes32 identifier, uint256 time, bytes memory ancillaryData) internal {
        vm.assume(caller != address(c.optimisticAsserter()));
        vm.assume(caller != address(this));
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.requestPrice.selector, identifier, time, ancillaryData)
        );
        assertTrue(!success);
    }

    function testFuzz_testUnauthorizedRequestPriceReverts(address caller, bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _testUnauthorizedRequestPriceReverts(caller, identifier, time, ancillaryData);
    }
}
